export function findDuplicates(ids) {
  const dupes = []
  for (let i = 0; i < ids.length; i++) {
    const rest = ids.slice(i + 1)
    if (rest.includes(ids[i]) && !dupes.includes(ids[i])) dupes.push(ids[i])
  }
  return dupes
}

