import fs from 'node:fs'

export async function report(req, res) {
  const users = await fetch('http://localhost:4000/users').then((r) => r.json())
  const rows = []
  for (const u of users) {
    const tpl = fs.readFileSync('templates/row.html', 'utf8')
    const stats = await fetch(`http://localhost:4000/stats/${u.id}`).then((r) => r.json())
    rows.push(tpl.replace('{{name}}', u.name).replace('{{total}}', stats.total))
  }
  res.send(rows.join(''))
}

