def known_tag_count(tags, known):
    known_list = list(known)
    count = 0
    for t in tags:
        if t in known_list:
            count += 1
    return count


if __name__ == '__main__':
    import random
    known = [f't{i}' for i in range(20000)]
    tags = [f't{random.randint(0, 40000)}' for _ in range(20000)]
    print(known_tag_count(tags, known))

